static void Set(CrashAnalysis& lrAnalysis, const Record& lrRecord)
{
    lrAnalysis.mxEventFlags                = lrRecord.muFlags;
    lrAnalysis.mbIsPlayerCrashing          = lrRecord.miCrashing != 0;
    lrAnalysis.mbSuggestLeftOfLineOfAction = lrRecord.miLeft != 0;
}

static bool Same(const CrashAnalysis& lrAnalysis, const Record& lrRecord)
{
    return lrAnalysis.mxEventFlags == lrRecord.muFlags
        && lrAnalysis.mbIsPlayerCrashing == (lrRecord.miCrashing != 0)
        && lrAnalysis.mbSuggestLeftOfLineOfAction == (lrRecord.miLeft != 0);
}

