{
    alignas(16) static u8 saInputStorage[64] = {};
    const DirectorIO::InputBuffer* lpInput = reinterpret_cast<const DirectorIO::InputBuffer*>(saInputStorage);
    static GameState sGameState;
    const EActiveRaceCarIndex lePlayer = static_cast<EActiveRaceCarIndex>(2);

    char lacName[256];
    const int kiRows = static_cast<int>(sizeof(kaRows) / sizeof(kaRows[0]));
    for (int liRow = 0; liRow < kiRows; ++liRow)
    {
        const Row& lrRow = kaRows[liRow];
        std::memset(&gCrashInfo, 0, sizeof(gCrashInfo));
        gCrashInfo.mvCollisionNormal = Vector3{ lrRow.mafNormal[0], lrRow.mafNormal[1], lrRow.mafNormal[2], 0.0f };
        gCrashInfo.mbHardstopVsWall = lrRow.miWall != 0;
        gCrashInfo.mbHardStopVsAI   = lrRow.miAI != 0;
        Camera::VehicleInfo& lrCar = gaRaceCars[lePlayer];
        Matrix44Affine& lrM = lrCar.mRaceCarState.mTransform;
        lrM.xAxis = Vector3{ lrRow.mafTransform[0], lrRow.mafTransform[1], lrRow.mafTransform[2], 0.0f };
        lrM.yAxis = Vector3{ lrRow.mafTransform[3], lrRow.mafTransform[4], lrRow.mafTransform[5], 0.0f };
        lrM.zAxis = Vector3{ lrRow.mafTransform[6], lrRow.mafTransform[7], lrRow.mafTransform[8], 0.0f };
        lrM.wAxis = Vector3{ lrRow.mafTransform[9], lrRow.mafTransform[10], lrRow.mafTransform[11], 0.0f };
        lrCar.mAABB.mMin = Vector3{ lrRow.mafMin[0], lrRow.mafMin[1], lrRow.mafMin[2], 0.0f };
        lrCar.mAABB.mMax = Vector3{ lrRow.mafMax[0], lrRow.mafMax[1], lrRow.mafMax[2], 0.0f };
        sGameState.mbCrashActive = lrRow.miCrashActive != 0;

        CrashAnalyser lAnalyser;
        Set(lAnalyser.mAnalysis, lrRow.maBefore[0]);
        Set(lAnalyser.mLastAnalysis, lrRow.maBefore[1]);
        Set(lAnalyser.mAnalysisAtLastShotChange, lrRow.maBefore[2]);

        lAnalyser.Update(lpInput, &sGameState, lePlayer);

        std::snprintf(lacName, sizeof(lacName), "Update [%s]: mAnalysis == console (got 0x%X/%d/%d)", lrRow.mpcName,
                      lAnalyser.mAnalysis.mxEventFlags, lAnalyser.mAnalysis.mbIsPlayerCrashing ? 1 : 0,
                      lAnalyser.mAnalysis.mbSuggestLeftOfLineOfAction ? 1 : 0);
        Check(Same(lAnalyser.mAnalysis, lrRow.maAfter[0]), lacName);
        std::snprintf(lacName, sizeof(lacName), "Update [%s]: mLastAnalysis == console", lrRow.mpcName);
        Check(Same(lAnalyser.mLastAnalysis, lrRow.maAfter[1]), lacName);
        std::snprintf(lacName, sizeof(lacName), "Update [%s]: mAnalysisAtLastShotChange untouched", lrRow.mpcName);
        Check(Same(lAnalyser.mAnalysisAtLastShotChange, lrRow.maAfter[2]), lacName);
    }

    // The accessor pair is reached once each per call (GetPlayerCrashInfo, GetRaceCarInfo).
    Check(giAccessorCalls == 2 * kiRows, "Update: GetPlayerCrashInfo + GetRaceCarInfo once each per call");

    // The inline surface (DWARF :46 / :82 / :85 / :88).
    {
        CrashAnalyser lAnalyser;
        Set(lAnalyser.mAnalysis, Record{ 0xA9u, 1, 0 });
        Set(lAnalyser.mLastAnalysis, Record{ 0x2Bu, 1, 1 });
        Set(lAnalyser.mAnalysisAtLastShotChange, Record{ 0u, 0, 0 });
        lAnalyser.SetShotChanged();
        Check(Same(lAnalyser.mAnalysisAtLastShotChange, Record{ 0x2Bu, 1, 1 }),
              "SetShotChanged: mAnalysisAtLastShotChange = mLastAnalysis (PS3 @0x15048; X360 inline 0x82274F90)");
        Check(&lAnalyser.GetAnalysis() == &lAnalyser.mAnalysis, "GetAnalysis: mAnalysis");
        Check(&lAnalyser.GetAnalysisAtLastShotChange() == &lAnalyser.mAnalysisAtLastShotChange,
              "GetAnalysisAtLastShotChange: mAnalysisAtLastShotChange");
        CrashAnalysis lCleared;
        Set(lCleared, Record{ 0xFFu, 1, 0 });
        lCleared.Clear();
        Check(Same(lCleared, Record{ 0u, 0, 1 }),
              "CrashAnalysis::Clear: flags 0, crashing false, suggest-left TRUE (0x82209570..78)");
        Check(sizeof(CrashAnalysis) == 8 && sizeof(CrashAnalyser) == 0x18,
              "layout: CrashAnalysis 8 bytes, CrashAnalyser 0x18 (the console's word copies)");
    }

    // ShotSelector::Prepare / Update / SetLastUsedToNow (PS3 @0x15000 / @0x2E4AC / @0x2E33C; inlined on the
    // X360 at MainDirector::Prepare 0x8224FBE4 and MainDirector::Update 0x82274FB0..0x82274FE4).
    {
        static ShotSelector sSelector;
        for (u32 luList = 0; luList < ShotSelector::KU_NUM_SHOT_LISTS; ++luList)
        {
            sSelector.maaShotTimes[luList].SetFullCount();
            for (u32 luSlot = 0; luSlot < ShotSelector::KU_SHOT_LIST_SIZE; ++luSlot)
                sSelector.maaShotTimes[luList].GetItem(luSlot) = 0;
        }
        sSelector.miCurrentTimeID = 77;
        const bool lbPrepared = sSelector.Prepare();
        Check(lbPrepared, "ShotSelector::Prepare: returns true");
        Check(sSelector.miCurrentTimeID == 0, "ShotSelector::Prepare: miCurrentTimeID = 0 (stw 0 -> +0x264)");

        static Camera::Camera sCamera;
        sCamera.mShotSelectionInfo.miType = -1;
        sCamera.mShotSelectionInfo.miId   = -1;
        sSelector.Update(sCamera);
        Check(sSelector.miCurrentTimeID == 1, "ShotSelector::Update: the clock ticks every frame");
        bool lbAnyStamp = false;
        for (u32 luList = 0; luList < ShotSelector::KU_NUM_SHOT_LISTS; ++luList)
            for (u32 luSlot = 0; luSlot < ShotSelector::KU_SHOT_LIST_SIZE; ++luSlot)
                lbAnyStamp = lbAnyStamp || sSelector.maaShotTimes[luList].GetItem(luSlot) != 0;
        Check(!lbAnyStamp, "ShotSelector::Update: a camera with no shot (miType == -1) stamps nothing");

        sCamera.mShotSelectionInfo.miType = 1;
        sCamera.mShotSelectionInfo.miId   = 7;
        sSelector.Update(sCamera);
        Check(sSelector.miCurrentTimeID == 2, "ShotSelector::Update: ticks again");
        Check(sSelector.maaShotTimes[1].GetItem(7) == 2, "ShotSelector::Update: stamps maaShotTimes[type][id] = now");
        Check(sSelector.maaShotTimes[0].GetItem(7) == 0 && sSelector.maaShotTimes[1].GetItem(6) == 0
              && sSelector.maaShotTimes[2].GetItem(7) == 0,
              "ShotSelector::Update: only that one slot");
    }

    // VehicleTracker::Update's crash-energy band @0x8223B3B8..0x8223B414 (the production
    // BrnDirectorVehicleTracker.cpp). Expected values are the asm's branches, stated per row:
    //   force && mbHardstopVsWall                -> HIGH (3)     0x8223B3C8 -> 0x8223B410
    //   speed <  max - 50 (flt_82CDA548)        -> LOW (1)      fcmpu / bge  @0x8223B3F4
    //   speed <  max - 20 (flt_82CDA54C)        -> NORMAL (2)   fcmpu / blt  @0x8223B404
    //   otherwise (incl. a NaN speed)            -> HIGH (3)
    {
        struct TrackerRow { const char* mpcName; f32 mfSpeed; f32 mfMax; int miForce; int miWall; int miExpected; };
        const TrackerRow kaTrackerRows[] =
        {
            { "60 mph in a 120 mph car: LOW",                  60.0f, 120.0f, 0, 0, 1 },
            { "69.99 mph (just under max - 50): LOW",          69.99f, 120.0f, 0, 0, 1 },
            { "70 mph (== max - 50, not <): NORMAL",           70.0f, 120.0f, 0, 0, 2 },
            { "80 mph: NORMAL",                                80.0f, 120.0f, 0, 0, 2 },
            { "100 mph (== max - 20, not <): HIGH",           100.0f, 120.0f, 0, 0, 3 },
            { "130 mph: HIGH",                                130.0f, 120.0f, 0, 0, 3 },
            { "NaN speed: HIGH (both compares fail)",          KF_NAN, 120.0f, 0, 0, 3 },
            { "force + wall hard stop at 10 mph: HIGH",        10.0f, 120.0f, 1, 1, 3 },
            { "force without a wall hard stop: the band",      10.0f, 120.0f, 1, 0, 1 },
            { "wall hard stop without force: the band",        80.0f, 120.0f, 0, 1, 2 },
        };
        GameState lGameState;
        lGameState.mEventState.SetAll(GameState::E_EVENT_STATE_PRE_INTRO);   // not racing: the ramp holds 0
        gUsedRaceCars.UnSetAll();
        gUsedRaceCars.SetBit(2u);
        char lacTracker[256];
        for (const TrackerRow& lrRow : kaTrackerRows)
        {
            std::memset(&gCrashInfo, 0, sizeof(gCrashInfo));
            gCrashInfo.mfSpeedMPH       = lrRow.mfSpeed;
            gCrashInfo.mbHardstopVsWall = lrRow.miWall != 0;
            Camera::VehicleInfo& lrCar = gaRaceCars[2];
            lrCar.mRaceCarState.mfMaxSpeedMPH = lrRow.mfMax;

            static VehicleTracker sTracker;
            sTracker.Construct();
            sTracker.SetVehicleIndex(2);

            lrCar.mRaceCarState.mbCrashing = false;
            sTracker.Update(&lGameState, lpInput, lePlayer, lrRow.miForce != 0);
            lrCar.mRaceCarState.mbCrashing = true;
            sTracker.Update(&lGameState, lpInput, lePlayer, lrRow.miForce != 0);
            std::snprintf(lacTracker, sizeof(lacTracker), "VehicleTracker band [%s] (got %d)", lrRow.mpcName,
                          static_cast<int>(sTracker.GetCrashType()));
            Check(static_cast<int>(sTracker.GetCrashType()) == lrRow.miExpected, lacTracker);
            std::snprintf(lacTracker, sizeof(lacTracker), "VehicleTracker [%s]: first frame of crash", lrRow.mpcName);
            Check(sTracker.IsFirstFrameOfCrash(), lacTracker);

            // The band is taken once, on the crash's first frame: a later frame keeps it.
            gCrashInfo.mfSpeedMPH = 1.0f;
            sTracker.Update(&lGameState, lpInput, lePlayer, false);
            std::snprintf(lacTracker, sizeof(lacTracker), "VehicleTracker [%s]: held while crashing", lrRow.mpcName);
            Check(static_cast<int>(sTracker.GetCrashType()) == lrRow.miExpected && !sTracker.IsFirstFrameOfCrash(),
                  lacTracker);
            lrCar.mRaceCarState.mbCrashing = false;
            sTracker.Update(&lGameState, lpInput, lePlayer, false);
            std::snprintf(lacTracker, sizeof(lacTracker), "VehicleTracker [%s]: back to NOT_CRASHING", lrRow.mpcName);
            Check(sTracker.GetCrashType() == VehicleTracker::E_CRASH_NOT_CRASHING, lacTracker);
        }
        Check(VehicleTracker::sfMinSpeedBelowMaxMPHForNormalCrash == 50.0f
              && VehicleTracker::sfMinSpeedBelowMaxMPHForHighSpeedCrash == 20.0f,
              "VehicleTracker bands: 50.0 @0x82CDA548 / 20.0 @0x82CDA54C (x360rd)");
    }

    // DebugLog::Construct / Clear (PS3 @0x22158 / @0x21F48; inlined by MainDirector::Construct
    // 0x8225B824..0x8225B87C) over the zero memory the director module starts from, then 25 appends
    // through the production ActualAppend (the pool holds 20; the oldest is recycled).
    {
        const int kiAssertsBefore = giAsserts;
        alignas(16) static u8 saLogStorage[sizeof(DebugLog)];
        std::memset(saLogStorage, 0, sizeof(saLogStorage));
        DebugLog& lrLog = *reinterpret_cast<DebugLog*>(saLogStorage);
        lrLog.Construct();
        Check(lrLog.mfStringDuration == 10.0f, "DebugLog::Construct: mfStringDuration = 10.0 (flt_82004A20)");
        Check(lrLog.mStringPool.miNumObjectsFree == 20 && lrLog.mStringIndices.GetLength() == 0,
              "DebugLog::Construct: the pool all free (20), the live order empty");
        Check(lrLog.mStringPool.maiObjectFreeQueue[0] == 19 && lrLog.mStringPool.maiObjectFreeQueue[19] == 0,
              "DebugLog::Clear: the free queue 19..0 (0x8225B858 loop)");
        char lacLine[32];
        for (int liLine = 0; liLine < 25; ++liLine)
        {
            std::snprintf(lacLine, sizeof(lacLine), "line %d", liLine);
            lrLog.Append(lacLine, CgsDev::RGBA());
        }
        Check(giAsserts == kiAssertsBefore, "DebugLog: 25 appends into the constructed log fire no assert");
        Check(lrLog.mStringIndices.GetLength() == 20
              && std::strcmp(lrLog.mStringPool[lrLog.mStringIndices[0]].macString, "line 5") == 0
              && std::strcmp(lrLog.mStringPool[lrLog.mStringIndices[19]].macString, "line 24") == 0,
              "DebugLog: a full log recycles its oldest line (lines 5..24 live, in order)");
        lrLog.Clear();
        Check(lrLog.mStringPool.miNumObjectsFree == 20 && lrLog.mStringIndices.GetLength() == 0,
              "DebugLog::Clear: back to all free / empty");
    }

    // MomentHardStop's "still upright" gate, KF_MAX_DOT_PRODUCT_FOR_HARD_STOP (PS3 name; X360 .bss
    // 0x82FAA848, written by the dyn-init thunk 0x82C484E0: (f32)cos(lfd 0x8200D520) -> 0x3F12D5E8).
    // The runner lifts the production definition out of BrnMomentHardStop.cpp into fxd2_hardstop.
    {
        u32 luBits = 0;
        std::memcpy(&luBits, &fxd2_hardstop::KF_MAX_DOT_PRODUCT_FOR_HARD_STOP, sizeof(luBits));
        char lacUpright[160];
        std::snprintf(lacUpright, sizeof(lacUpright),
                      "KF_MAX_DOT_PRODUCT_FOR_HARD_STOP == 0x3F12D5E8 (cos 55 deg; got 0x%08X)", luBits);
        Check(luBits == 0x3F12D5E8u, lacUpright);
        // The gate is `yAxis.y > KF` (vcmpgtfp. @0x82271938): a car tilted 54 deg passes, 56 deg does not.
        const f32 kfDegToRad = 0.017453292f;
        Check(static_cast<f32>(std::cos(54.0f * kfDegToRad)) > fxd2_hardstop::KF_MAX_DOT_PRODUCT_FOR_HARD_STOP,
              "upright gate: a 54-degree tilt is still a hard stop");
        Check(!(static_cast<f32>(std::cos(56.0f * kfDegToRad)) > fxd2_hardstop::KF_MAX_DOT_PRODUCT_FOR_HARD_STOP),
              "upright gate: a 56-degree tilt is not");
    }

    Check(giAsserts == 0, "no assert fired");

    std::printf("fxdirector2_crash_analyser: %d checks, %d failures\n", giChecks, giFailures);
    return giFailures == 0 ? 0 : 1;
}
